-- Duskwood: creature abilities
-- Most of the zone's creatures (Nightbane worgen, the undead of Raven Hill and the Darkshire cemeteries, the Splinter Fist ogres,
-- the wildlife) had no AI or ran classic rows. Duskwood is the Cataclysm revamp, so port their abilities from the Cataclysm data,
-- and from the classic data where Cataclysm has none (Lord Malathrom), keeping the scripts already in place. The Skeletal Warriors,
-- Venom Web Spiders and Black Widow Hatchlings keep their classic abilities next to the single Cataclysm one, and Morbent Fel gets
-- the Unholy Shield his Sacred Cleansing quest removes. The Lurking Worgen and Watcher Eva, which no reference scripts, cast
-- their sniffed spells (creature_template spell1-8).

SET @ENTRIES := '3,48,202,205,206,210,212,217,218,300,315,503,507,511,521,522,533,534,574,604,628,889,898,920,930,948,1251,1270,3946,10038,37984,43731,43761,43862,43923,44016,44020,44028,44029,44087,44089,45614,45619,45739,45771,45801,45811';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '45740';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
